brokenCode.code:
const original = [1, 2, 3];
const copy = original; // not a copy!
copy.push(4);

console.log(original); // [1, 2, 3, 4] — original changed too!

solution.code:
const original = [1, 2, 3];
const copy = [...original]; // shallow copy (or original.slice())
copy.push(4);

console.log(original); // [1, 2, 3] — unchanged
console.log(copy); // [1, 2, 3, 4]

function rotateRight(arr, k) {
  const n = arr.length;
  if (n === 0) return [];
  const shift = k % n;
  return [...arr.slice(n - shift), ...arr.slice(0, n - shift)];
}

console.log(rotateRight([1, 2, 3, 4, 5], 2)); // [4, 5, 1, 2, 3]
